 $('#invite-account-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;$('#access-form-error').textContent='';try{const values=Object.fromEntries(new FormData(event.target)),type=$('#invite-type').value,portal=PORTAL==='ubl'?'ubl':type==='technician'?'technician':type==='ubl-admin'?'ubl':'powervision',role=portal==='technician'?'technician':portal==='powervision'?'ho':type==='branch'?'branch':'client_ho';const result=await api('accounts',{name:values.name,email:values.email,employeeId:values.employeeId,portal,role,admin:type==='ubl-admin'||(['ho','vendor','client_ho'].includes(role)&&values.admin==='on'),...(role==='branch'?{branchCode:values.branchCode}:{})});await loadTeam();showInvitation(result);}catch(error){$('#access-form-error').textContent=error.message;}finally{button.disabled=false;}};
