 const labels={disable:'Disable account access',enable:'Enable account access',reset:'Reset account password',reinvite:'Reissue activation link'},descriptions={disable:'This person will be signed out and cannot sign in while their account is disabled.',enable:'Restore access for this person. An account that has not been activated will receive a new activation link.',reset:'The current password and existing sessions will stop working. A new private activation link lets this person set a password.',reinvite:'Create a replacement activation link. Any earlier unused activation link will stop working.'};
