 accessDialog('Change your password',`<p class="access-form-intro">Update the password for ${esc(user.email)}. You will sign in again after the change.</p><form id="password-change-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" maxlength="128" required></label><label>New password<input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>Confirm new password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><p class="access-form-help">Use at least 12 characters.</p><p id="access-form-error" class="danger" role="alert"></p><div class="access-form-actions"><button class="button" type="submit">Update password</button></div></form>`);
