 const headings={overview:['Operations overview','Track your branch network and monthly service progress.'],visits:['Service visits','Follow assigned visits from scheduling to client acknowledgement.'],reports:['Field service reports','Review complete technician records, evidence and revision history.'],amc:['AMC Excel report','Review and download the monthly client workbook from submitted service records.'],assets:['Genset asset register','Find the equipment linked to your authorized service visits.'],inventory:['Inventory management','Track PowerVision parts, stock receipts and technician material usage.'],team:[PORTAL==='ubl'?'UBL team & access':'People & technicians','Manage invitations, account access and your registered team.'],payments:['Payment reconciliation','Review branch-acknowledged AMC visits and the monthly statement.'],audit:['Audit history','Trace recorded service submissions and client decisions.']};
