function table(rows){return `<div class="table-scroll"><table><thead><tr><th>Branch / Genset</th><th>Region</th><th>Due date</th><th>Coverage</th><th>Visit status</th><th></th></tr></thead><tbody>${rows.length?rows.map(visit=>`<tr><td><b>${esc(visit.branchName)}</b><small>${esc(recordClient(visit))} · ${esc(visit.branchCode)} · ${esc(visit.assetId)}</small>${PORTAL==='powervision'?`<small class="visit-technician-label">${esc(technicians.find(person=>person.id===visit.technicianId)?.name??visit.technicianName??(visit.technicianId?'Assigned technician':'Unassigned'))}</small>`:''}</td><td>${esc(visit.region)}</td><td>${esc(visit.dueDate)}${visit.status==='scheduled'&&visit.dueDate<new Date().toISOString().slice(0,10)?'<small class="danger">Overdue</small>':''}</td><td>${badge(visit.warranty)}</td><td>${badge(visit.status)}</td><td><div class="visit-record-actions"><button class="text-button" data-visit="${esc(visit.id)}">${user.role==='technician'&&['scheduled','unacknowledged'].includes(visit.status)?'Complete FSR':'View record'} ${icon('arrow')}</button>${canAssign(visit)?`<button class="text-button assign-visit-button" data-assign="${esc(visit.id)}">${icon('person')}Assign technician</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No visits match these filters. Adjust or reset the filters above.</td></tr>'}</tbody></table></div>`;}

const safePhoto=value=>typeof value==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value)?value:null;
const reportValue=value=>value===undefined||value===null||value===''?'—':String(value);
function reportSections(fsr){
 const groups=[...new Set(fields.map(field=>field.group))];
 return groups.map((group,index)=>`<details class="report-section" id="report-section-${index}" open><summary><span class="section-number">${String(index+1).padStart(2,'0')}</span>${esc(group)}<small>${fields.filter(field=>field.group===group).length} fields</small></summary><div class="record-grid">${fields.filter(field=>field.group===group).map(field=>{
  const photo=field.type==='attachment'?safePhoto(fsr[field.key]):null;
  return `<div class="record-field ${field.type==='attachment'?'record-photo':''}"><small>${esc(field.label)}</small>${field.type==='attachment'?(photo?`<img class="evidence" alt="${esc(field.label)} submitted by the technician" src="${esc(photo)}">`:'<span class="missing-evidence">No photograph recorded</span>'):`<b>${esc(reportValue(fsr[field.key]))}</b>`}</div>`;
 }).join('')}</div></details>`).join('');
}
function reportMaterialUsage(fsr){
 const recorded=Array.isArray(fsr.inventoryUsage),usage=recorded?fsr.inventoryUsage:[];
 return `<details class="report-section report-materials" id="report-materials" open><summary><span class="section-number">${icon('inventory')}</span>Tracked parts & materials<small>${recorded?usage.length+' items':'Not recorded'}</small></summary>${usage.length?`<div class="table-scroll"><table data-inventory-usage><thead><tr><th>Material / SKU</th><th>Quantity used</th><th>Unit</th></tr></thead><tbody>${usage.map(item=>`<tr><td><b>${esc(item.name??item.sku??item.itemId)}</b><small>${esc(item.sku??'')}</small></td><td>${quantity(item.quantity)}</td><td>${esc(item.unit??'—')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="report-materials-empty">${recorded?'No tracked material recorded for this submission.':'Structured material usage was not recorded in this earlier report.'}</p>`}</details>`;
}
function reportActivity(report){
 const labels={'visit.started':'Visit started','fsr.submitted':'Technician submitted an FSR','fsr.acknowledged':'Client acknowledged the report','fsr.unacknowledged':'Client requested a correction'};
 const activity=report.activity??[];
 if(!activity.length)return '';
 return `<section class="report-activity"><div class="panel-heading"><div><span class="eyebrow">SERVICE TIMELINE</span><h3>Visit and client decisions</h3></div></div>${activity.map(action=>`<div class="audit-row"><span class="audit-symbol">${icon(action.action.includes('acknowledged')?'shield':'audit')}</span><div><b>${esc(labels[action.action]??action.action.replaceAll('.',' · '))}</b><small>${esc(action.actorName??users.find(account=>account.id===action.actor)?.name??action.actor)} · ${esc(dateTime(action.at))}</small>${action.detail?.reason?`<p>${esc(action.detail.reason)}</p>`:''}</div></div>`).join('')}</section>`;
}
function comparisonValues(fsr,group){return fields.filter(field=>field.group===group).map(field=>`<div><small>${esc(field.label)}</small><b>${field.type==='attachment'?(safePhoto(fsr[field.key])?'Image recorded':'Not recorded'):esc(reportValue(fsr[field.key]))}</b></div>`).join('');}
function verificationStatus(entry){return entry?`<span class="badge verification-${esc(entry.decision)}">${entry.decision==='matched'?'Matched':'Mismatch reported'}</span>`:'<span class="badge verification-pending">Pending manual review</span>';}
function paperComparison(report,fsr,isLatest,revision){
 const verification=report.verification??{history:[]},entries=verification.history??[],photo=safePhoto(fsr.fsrPhoto),groups=[...new Set(fields.map(field=>field.group))],defaultGroup=fsr.fsrTemplate==='PVS-FSR-V02'?groups.find(group=>group==='Paper FSR / Customer Details')||groups[0]:groups[0];
 const company=entries.find(entry=>entry.revision===revision&&entry.scope==='company')??(revision===verification.revision?verification.company:null),client=entries.find(entry=>entry.revision===revision&&entry.scope==='client')??(revision===verification.revision?verification.client:null);
 const companyName=report.company?.name||report.visit.vendor||'Company',clientName=report.client?.name||'Client',userVendor=user.vendor==='Demo AMC Services'?COMPANY:user.vendor;
 const companyReview=report.asset?.vendor===companyName&&report.visit.vendor===companyName&&((user.role==='ho'&&companyName===COMPANY)||(user.role==='vendor'&&companyName===userVendor)),clientReview=['client_ho','branch'].includes(user.role)&&user.client===clientName&&(user.role!=='branch'||user.branchCode===report.visit.branchCode);
 const roleScope=companyReview?'company':clientReview?'client':null,canVerify=isLatest&&roleScope&&photo&&Number.isInteger(revision);
 return `<section class="paper-comparison" id="paper-comparison"><div class="comparison-heading"><div><span class="eyebrow">PAPER FSR & DIGITAL RECORD</span><h3>Compare the photograph with entered values</h3><p>Check the uploaded paper FSR manually. Each organization records its own result for this revision.</p></div><span class="comparison-manual-badge">${icon('person')}Manual check</span></div>
 <div class="verification-status-grid">${[['company',companyName+' verification',company],['client',clientName+' verification',client]].map(([scope,label,entry])=>`<article class="verification-status-card" data-verification-scope="${scope}"><span>${esc(label)}</span>${verificationStatus(entry)}${entry?`<small>${esc(entry.reviewer?.name??entry.actor?.name??'Reviewer')} · ${esc(dateTime(entry.at))}</small>${entry.reason?`<p>${esc(entry.reason)}</p>`:''}<small>${entry.fields?.length?entry.fields.length+' fields marked for comparison':'Whole-report comparison'}</small>`:'<p>This organization has not checked the image against this revision.</p>'}</article>`).join('')}</div>
 <div class="comparison-workspace"><div class="paper-evidence-panel"><div class="comparison-pane-heading"><b>Completed paper FSR</b>${photo?`<button class="text-button" id="open-paper-image">Expand image ${icon('external')}</button>`:''}</div>${photo?`<div class="paper-image-scroll"><img class="paper-comparison-image" src="${esc(photo)}" alt="Completed paper FSR uploaded by the technician; compare against the entered values"></div><p class="comparison-image-hint">Expand the image to zoom in on handwriting and check marks.</p>`:'<div class="missing-paper-image">'+icon('reports')+'<b>No completed paper FSR image recorded</b><p>Image verification remains pending until the technician provides the completed form.</p></div>'}</div>
 <div class="comparison-data-panel"><div class="comparison-pane-heading"><b>Technician-entered values</b></div><label for="comparison-section">Choose a form section</label><select id="comparison-section">${groups.map(group=>`<option value="${esc(group)}" ${group===defaultGroup?'selected':''}>${esc(group)}</option>`).join('')}</select><div id="comparison-values" class="comparison-values">${comparisonValues(fsr,defaultGroup)}</div></div></div>
 ${canVerify?`<form id="verification-form" class="verification-form"><div><span class="eyebrow">YOUR ORGANIZATION’S REVIEW</span><h3>Record ${esc(roleScope==='company'?companyName:clientName)} image verification</h3><p>This check is separate from branch acknowledgement and payment eligibility.</p></div><div class="verification-form-grid"><label>Comparison result<select name="decision" id="verification-decision" required><option value="">Choose a result</option><option value="matched">Matched · image and entered values agree</option><option value="mismatch">Mismatch · correction is needed</option></select></label><label>Review notes<textarea name="reason" maxlength="4000" id="verification-reason" placeholder="Describe a mismatch or add review notes."></textarea></label></div><details class="verification-field-picker"><summary>Mark specific fields checked <small>Optional · otherwise whole report</small></summary><div class="verification-check-actions"><button type="button" class="text-button" id="check-all-verification">Select all fields</button><button type="button" class="text-button" id="clear-verification-fields">Clear selection</button></div><div class="verification-field-groups">${groups.map(group=>`<fieldset><legend>${esc(group)}</legend>${fields.filter(field=>field.group===group).map(field=>`<label><input type="checkbox" name="checkedField" value="${esc(field.key)}"><span>${esc(field.label)}</span></label>`).join('')}</fieldset>`).join('')}<fieldset><legend>Stock usage</legend><label><input type="checkbox" name="checkedField" value="inventoryUsage"><span>Tracked parts & materials</span></label></fieldset></div></details><p id="verification-error" class="danger" role="alert"></p><div class="verification-form-actions"><span>A new FSR revision needs a new check from each organization.</span><button class="button" type="submit">${icon('check')}Save verification</button></div></form>`:!isLatest?'<p class="comparison-readonly-note">Historical revision: verification results are shown for reference. Open the latest revision to record a new check.</p>':!roleScope?`<p class="comparison-readonly-note">${esc(companyName)} management and the authorized client record their own verification decisions.</p>`:''}
 <details class="verification-history"><summary>Image verification history <small>${entries.length} recorded decisions</small></summary>${entries.length?entries.map(entry=>{const ordinal=report.history.findIndex(version=>version.revision===entry.revision)+1;return `<div class="verification-history-row"><div><b>${esc(entry.scope==='company'?entry.vendor||companyName:entry.client||clientName)} · ${ordinal?'Revision '+ordinal:'Revision reference '+esc(entry.revision)}</b>${verificationStatus(entry)}<small>${esc(entry.reviewer?.name??entry.actor?.name??'Reviewer')} · ${esc(entry.reviewer?.employeeId??entry.actor?.employeeId??'')} · ${esc(dateTime(entry.at))}</small>${entry.reason?`<p>${esc(entry.reason)}</p>`:''}<small>${entry.fields?.length?esc(entry.fields.map(key=>fields.find(field=>field.key===key)?.label??(key==='inventoryUsage'?'Tracked parts & materials':key)).join(', ')):'Whole-report comparison'}</small></div></div>`;}).join(''):'<p>No image verification decisions have been recorded.</p>'}</details></section>`;
}
function openPaperImage(source){
 const photo=safePhoto(source);if(!photo)return;const dialog=$('#evidence-detail');dialog.className='evidence-dialog';
 dialog.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">COMPLETED PAPER FSR</span><h2>Photograph review</h2></div><button class="close-button" id="close-evidence" aria-label="Close photograph">${icon('close')}</button></div><div class="image-zoom-controls"><label for="evidence-zoom">Image zoom</label><input type="range" id="evidence-zoom" min="50" max="250" step="25" value="100"><output id="evidence-zoom-value" for="evidence-zoom">100%</output><button class="text-button" id="fit-evidence">Reset zoom</button></div><div class="evidence-image-scroll"><img id="expanded-evidence" src="${esc(photo)}" alt="Completed paper field service report photograph"></div><p class="comparison-image-hint">Use the zoom control, then scroll the image to inspect the form.</p>`;
 if(!dialog.open)dialog.showModal();$('#close-evidence').onclick=()=>dialog.close();const zoom=()=>{$('#expanded-evidence').style.width=$('#evidence-zoom').value+'%';$('#evidence-zoom-value').textContent=$('#evidence-zoom').value+'%';};$('#evidence-zoom').oninput=zoom;$('#fit-evidence').onclick=()=>{$('#evidence-zoom').value='100';zoom();};
}
function bindComparison(report,fsr){
 $('#comparison-section')?.addEventListener('change',event=>{$('#comparison-values').innerHTML=comparisonValues(fsr,event.target.value);});$('#open-paper-image')?.addEventListener('click',()=>openPaperImage(fsr.fsrPhoto));
 $('#verification-decision')?.addEventListener('change',event=>{$('#verification-reason').required=event.target.value==='mismatch';});
 $('#check-all-verification')?.addEventListener('click',()=>document.querySelectorAll('#verification-form [name="checkedField"]').forEach(input=>input.checked=true));
 $('#clear-verification-fields')?.addEventListener('click',()=>document.querySelectorAll('#verification-form [name="checkedField"]').forEach(input=>input.checked=false));
 $('#verification-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter,account=user.id,version=detailVersion;button.disabled=true;$('#verification-error').textContent='';try{const input=new FormData(event.target);await api(`visits/${encodeURIComponent(report.visit.id)}/verify`,{revision:report.verification.revision,decision:input.get('decision'),reason:input.get('reason'),fields:input.getAll('checkedField')});const updated=await api(`visits/${encodeURIComponent(report.visit.id)}/report`);if(user.id!==account||version!==detailVersion||!$('#detail').open)return;$('#report-body').innerHTML=reportMarkup(updated,null);bindReport(updated);$('#paper-comparison').scrollIntoView({behavior:'smooth',block:'start'});notify('Your organization’s image verification has been recorded for this FSR revision.');}catch(error){if($('#verification-error'))$('#verification-error').textContent=error.message;}finally{button.disabled=false;}});
}
function reportMarkup(report,revisionIndex){
 const {visit,asset,technician,history}=report,selected=revisionIndex===null?null:history[revisionIndex],fsr=selected?.fsr??visit.fsr;
 const isLatest=!selected||revisionIndex===history.length-1,number=selected?revisionIndex+1:history.length||1;
 const clientName=fsr.client??report.client?.name??'Not recorded',technicianName=fsr.technicianName??technician?.name??fsr.technicianId??visit.technicianId,technicianEmployeeId=fsr.technicianEmployeeId??technician?.employeeId??fsr.technicianId??'Not recorded';
 return `<div class="report-title"><div class="report-company"><span class="brand-icon">${icon('bolt')}</span><div><strong>${esc(fsr.company??report.company?.name??COMPANY)}</strong><small>FIELD SERVICE REPORT · ${esc(clientName)}</small></div></div><div class="report-reference"><span>FSR reference</span><b>${esc(fsr.fsrNumber)}</b></div></div>
 <div class="report-branch-heading"><div><span class="eyebrow">${esc(clientName)} BRANCH ${esc(visit.branchCode)}</span><h2>${esc(visit.branchName)}</h2><p>${esc(fsr.siteAddress??asset?.siteAddress??'Site address not recorded')}</p></div>${badge(isLatest?visit.status:'revision '+number)}</div>
 <div class="report-toolbar"><span>${isLatest?'Latest submitted report':'Historical report · revision '+number} <small>· ${fields.length} FSR fields</small></span><div><label class="sr-only" for="report-jump">Jump to report section</label><select id="report-jump"><option value="">Jump to a section</option><option value="paper-comparison">Paper image comparison</option>${[...new Set(fields.map(field=>field.group))].map((group,index)=>`<option value="report-section-${index}">${esc(group)}</option>`).join('')}<option value="report-materials">Tracked parts & materials</option></select><button id="print-report" class="button">${icon('print')}Print report</button></div></div>
 <div class="report-metadata"><div><small>Client</small><b>${esc(clientName)}</b></div><div><small>Genset / Asset</small><b>${esc(visit.assetId)}</b></div><div><small>Technician</small><b>${esc(technicianName)}</b><span>${esc(technicianEmployeeId)}</span></div><div><small>Visit started · PKT</small><b>${esc(dateTime(fsr.visitStartedAt??visit.startedAt))}</b></div><div><small>Submitted · PKT</small><b>${esc(dateTime(fsr.submittedAt))}</b></div><div><small>Report version</small><b>Revision ${number}${isLatest?' · Latest':''}</b></div></div>
 ${!isLatest?'<div class="revision-warning">You are viewing an earlier technician submission. The client decision below applies to the latest report.</div>':''}
 ${visit.acknowledgement?`<div class="review-note"><div>${icon('shield')}<strong>Client decision on latest report</strong>${badge(visit.acknowledgement.decision)}</div><p>${esc(visit.acknowledgement.reason||'No review comments provided.')}</p><small>${esc(visit.acknowledgement.name??visit.acknowledgement.reviewer?.name??users.find(account=>account.id===visit.acknowledgement.userId)?.name??visit.acknowledgement.userId)} · ${esc(visit.acknowledgement.employeeId)} · ${esc(dateTime(visit.acknowledgement.at))}</small></div>`:'<div class="review-note awaiting-note">'+icon('shield')+'<span>Awaiting branch acknowledgement. This report is visible to the responsible company and the authorized client.</span></div>'}
 ${paperComparison(report,fsr,isLatest,selected?.revision??report.verification?.revision??history.at(-1)?.revision)}
 ${reportSections(fsr)}
 ${reportMaterialUsage(fsr)}
 <section class="revision-history"><div class="panel-heading"><div><span class="eyebrow">SUBMISSION HISTORY</span><h3>Report revisions</h3></div><small>Saved technician submissions</small></div>${history.length?history.map((entry,index)=>`<div class="revision-row"><span class="revision-marker">${index+1}</span><div><b>Revision ${index+1}${index===history.length-1?' · Latest submission':''}</b><small>${esc(dateTime(entry.fsr.submittedAt))} · ${esc(entry.fsr.technicianName??technician?.name??entry.fsr.technicianId??'Technician')}</small></div><button class="text-button" data-revision="${index}" ${number===index+1?'disabled':''}>${number===index+1?'Viewing':'View revision'}</button></div>`).join(''):'<p>No previous revisions recorded.</p>'}</section>
 ${reportActivity(report)}
 ${isLatest&&user.role==='branch'&&visit.status==='submitted'?'<form id="review-form" class="branch-review-form"><span class="eyebrow">BRANCH REVIEW</span><h3>Confirm the technician’s service report</h3><label>Review comments<textarea name="reason" placeholder="Describe corrections if the report cannot be acknowledged."></textarea></label><p class="review-help">A reason is required when requesting a correction.</p><p id="form-error" class="danger" role="alert"></p><div class="review-actions"><button class="button" name="decision" value="acknowledged">'+icon('check')+'Acknowledge report</button><button class="button secondary" name="decision" value="unacknowledged">Request correction</button></div></form>':''}
 <div class="report-footnote">Shared service record · ${esc(fsr.company??report.company?.name??COMPANY)} / ${esc(clientName)} · Development demo</div>`;
}
function bindReport(report){
 const selectedRevisionButton=document.querySelector('[data-revision][disabled]'),selectedIndex=selectedRevisionButton?Number(selectedRevisionButton.dataset.revision):report.history.length-1;bindComparison(report,report.history[selectedIndex]?.fsr??report.visit.fsr);
 $('#report-jump')?.addEventListener('change',event=>{const target=document.getElementById(event.target.value);if(target){target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'});}});
 $('#print-report')?.addEventListener('click',()=>{const title=document.title,sections=[...document.querySelectorAll('#report-body details')],states=sections.map(section=>section.open);try{document.title=`${COMPANY} · ${report.visit.fsr.fsrNumber}`;sections.forEach(section=>section.open=true);window.print();}finally{document.title=title;sections.forEach((section,index)=>section.open=states[index]);}});
 document.querySelectorAll('[data-revision]').forEach(button=>button.onclick=()=>{const scroll=$('#detail').scrollTop;$('#report-body').innerHTML=reportMarkup(report,Number(button.dataset.revision));bindReport(report);$('#detail').scrollTop=Math.min(scroll,180);});
 $('#review-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api(`visits/${encodeURIComponent(report.visit.id)}/review`,{decision:button.value,reason:new FormData(event.target).get('reason')});$('#detail').close();await refresh();notify('Client decision recorded. The updated status is available to PowerVision and the authorized client.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}});
}
function editableField(field,visit,asset){
 const required=!field.optional&&field.type!=='conditional'?'required':'',value=visit.fsr?.[field.key]??({model:asset?.model,engineSerial:asset?.engineSerial,rating:asset?.rating}[field.key]??'');
 let control;
 if(Array.isArray(field.type))control=`<select name="${esc(field.key)}" ${required}><option value="">Select…</option>${field.type.map(option=>`<option ${value===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`;
 else if(field.type==='attachment')control=`<input name="${esc(field.key)}" type="file" accept="image/jpeg,image/png,image/webp" ${required}>${field.optional&&safePhoto(value)?'<small class="optional-field-help">The existing image is retained if no replacement is selected.</small>':''}`;
 else control=`<input name="${esc(field.key)}" type="${['number','date','time'].includes(field.type)?field.type:'text'}" ${field.type==='number'?'min="0" step="any"':''} ${required} value="${esc(value)}">`;
 return `<label>${esc(field.label)}${field.optional?'<span class="optional-field-label">Optional</span>':''}${control}${field.help?`<small class="optional-field-help">${esc(field.help)}</small>`:''}</label>`;
}
function editableMarkup(visit,asset){
 const groups=[...new Set(fields.filter(field=>field.type!=='auto').map(field=>field.group))];
 return `<p class="form-introduction">Complete applicable fields and attach the completed paper FSR, before and after photographs (maximum 2 MB each). Paper-template additions and separate signature images are optional; leave unrecorded values blank.</p><div class="legacy-material-note">${icon('inventory')}<div><b>Parts and materials</b><p>Use the <a href="/technician/" target="_blank" rel="noopener">technician app</a> to select or change tracked stock usage. This form keeps the existing material quantities when you resubmit.</p></div></div>${visit.fsr?reportMaterialUsage(visit.fsr):''}${visit.acknowledgement?`<div class="review-note"><b>Client requested a correction</b><p>${esc(visit.acknowledgement.reason)}</p></div>`:''}<form id="fsr-form">${groups.map(group=>`<fieldset><legend>${esc(group)}</legend><div class="form-grid">${fields.filter(field=>field.group===group&&field.type!=='auto').map(field=>editableField(field,visit,asset)).join('')}</div></fieldset>`).join('')}<p id="form-error" class="danger" role="alert"></p><button class="button" type="submit">Submit FSR for branch review</button></form>`;
}
async function detail(id){
 const version=++detailVersion,requestedUser=user.id;let report;
 try{report=await api('visits/'+encodeURIComponent(id)+'/report');}catch(error){notify(error.message);return;}
 if(version!==detailVersion||requestedUser!==user.id)return;
 const visit=report.visit,editable=user.role==='technician'&&['scheduled','unacknowledged'].includes(visit.status),dialog=$('#detail');
 dialog.className=editable?'visit-dialog':'report-dialog';
 dialog.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${editable?'TECHNICIAN SERVICE FORM':'DETAILED SERVICE RECORD'}</span><span class="modal-heading-context">${esc(visit.assetId)} · Branch ${esc(visit.branchCode)}</span></div><button id="close" class="close-button" aria-label="Close service report">${icon('close')}</button></div>${editable?`<h2>${esc(visit.branchName)}</h2>${editableMarkup(visit,report.asset)}`:visit.fsr?`<div id="report-body">${reportMarkup(report,null)}</div>`:`<div class="unsubmitted-record"><div class="empty-icon">${icon('reports')}</div><h2>${esc(visit.branchName)}</h2><p>No field service report has been submitted for this visit.</p><div class="report-metadata"><div><small>Assigned technician</small><b>${esc(report.technician?.name??visit.technicianId)}</b></div><div><small>Scheduled date</small><b>${esc(visit.dueDate)}</b></div><div><small>Genset</small><b>${esc(visit.assetId)}</b></div><div><small>Status</small>${badge(visit.status)}</div></div>${PORTAL==='powervision'?`<a class="button" href="/technician/" target="_blank" rel="noopener">Open technician app ${icon('external')}</a>`:''}</div>`}`;
 if(!dialog.open)dialog.showModal();$('#close').onclick=()=>{detailVersion++;dialog.close();};
 if(visit.fsr&&!editable)bindReport(report);
 $('#fsr-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));values.fsrTemplate=visit.fsr?.fsrTemplate??'PVS-FSR-V02';if(Array.isArray(visit.fsr?.inventoryUsage))values.inventoryUsage=visit.fsr.inventoryUsage.map(item=>({itemId:item.itemId,quantity:item.quantity}));for(const field of fields.filter(field=>field.type==='attachment')){const file=values[field.key];if(field.optional&&(!file||!file.size)){delete values[field.key];continue;}if(file.size>2*1024*1024)throw new Error('Each image must be at most 2 MB');values[field.key]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Cannot read image'));reader.readAsDataURL(file);});}await api(`visits/${encodeURIComponent(id)}/submit`,values);dialog.close();await refresh();notify('FSR submitted. PowerVision and the authorized client can now view the complete report.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}});
}
async function boot(){
 try{user=await api('me');if(user.portal!==PORTAL)throw Object.assign(new Error('This account is not authorized for this portal.'),{status:403});const results=await Promise.all([api('map-config'),PORTAL==='powervision'&&teamAccess()?api('technicians').catch(()=>({technicians:[]})):Promise.resolve({technicians:[]})]);mapConfiguration=results[0];technicians=results[1].technicians??[];await refresh();}
 catch(error){if(error.status===401)return;$('#app').innerHTML=`<div class="startup-error"><h1>${error.status===403?'Portal access required':'Unable to load your workspace'}</h1><p>${esc(error.message)}</p>${error.status===403?`<a class="button" href="${PORTAL_HOME}">Return to ${PORTAL==='ubl'?'UBL':'PowerVision'} sign-in</a>`:'<button class="button" id="retry-startup">Try again</button>'}</div>`;$('#retry-startup')?.addEventListener('click',boot);}
}
boot();
setInterval(()=>{if(user&&tab==='overview'&&!refreshing&&!document.querySelector('dialog[open]')&&document.visibilityState==='visible'&&!document.activeElement?.matches('input,select,textarea'))refresh({background:true}).catch(()=>{const label=document.querySelector('.updated-at');if(label)label.textContent='Connection lost · trying again';});},15000);
